  def satisfiesReturnTypeRule(f: Functional, g: Functional): Boolean = {
    val fa = makeArrowFromFunctional(f, true).get
    val ga = makeArrowFromFunctional(g, true).get
    satisfiesReturnTypeRule(fa, ga)
  }

